var pos = {};
var colors = ["#FFC30F", "#581845", "#900C3F", "#C70039", "#FF5733", "#1AC7C4"];
var seed;

function setup() {
	createCanvas(windowWidth, windowHeight);

	colors.forEach((str, i) => colors[i] = color(str));
	seed = random() * 10000;

	pos.x = width/2;
	pos.y = height/2;
}

function draw() {
	randomSeed(seed);
	background(255);
	noStroke();
	for(var i = 0; i < 6; i++){
		var pallete = [random(colors), random(colors), random(colors), random(colors)];
		drawPill(300*((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))+1)/width + i * 80, 150*((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))+1)/height, 42, pallete, 10);		
	}
}

function mousePressed(){
	seed = random() * 10000;
}

function drawPill(w, h, size, colors, resolution){
	for(var a = -PI/2; a <= 0; a += (Math.max(0.001, Math.abs(PI/20 * 1/resolution)) || 1)){
		fill(lerpColors(map(a, -PI/2, 0, 0, 0.33), colors));
		var x = cos(a) * w/2;
		var y = -h/2 + sin(a) * w/2 + height/2;
		circle(x + width/2, y, size);
		circle(-x + width/2, y, size);
	}
	for(var yy = -h/2; yy <= h/2; yy += (Math.max(0.001, Math.abs(h/10 * 1/resolution)) || 1)) {
		fill(lerpColors(map(yy, -h/2, h/2, 0.33, 0.66), colors));
		var x = w/2;
		var y = yy + height/2;
		circle(x + width/2, y, size);
		circle(-x + width/2, y, size);
	}
	for(var a = 0; a <= PI/2; a += (Math.max(0.001, Math.abs(PI/20 * 1/resolution)) || 1)){
		fill(lerpColors(map(a, 0, PI/2, 0.66, 1), colors));
		var x = cos(a) * w/2;
		var y = h/2 + sin(a) * w/2 + height/2;
		circle(x + width/2, y, size);
		circle(-x + width/2, y, size);
	}
}

/**
 * lerp color from multiple color array
 * param {Integer} [t] lerp factor from 0 to 1
 * param {Array} [[color, color]] colors to lerp, minimum 2 colors in array
 */
function lerpColors(t, colors)
{
	let i = Math.floor(t*(colors.length-1));
	if(i < 0) return colors[0];
	if(i >= colors.length-1) return colors[colors.length-1];

	let percent = (t - i / (colors.length-1)) * (colors.length-1);
	return color(
		colors[i]._getRed() + percent*(colors[i+1]._getRed()-colors[i]._getRed()),
		colors[i]._getGreen() + percent*(colors[i+1]._getGreen()-colors[i]._getGreen()),
		colors[i]._getBlue() + percent*(colors[i+1]._getBlue()-colors[i]._getBlue())
	)
}
